"""Native axial stack for two common 6810 bearings and separate race retention."""
class PairedRollIntent:
 def __init__(self,g):self.g=g;self.c=g.component;self.d=g.design
 def parameters(self):
  values={'pr_bearing_id':50,'pr_bearing_od':65,'pr_bearing_width':7,'pr_bearing_center_span':14,'pr_seat_diametral_allowance':.15,'pr_journal_diametral_clearance':.1,'pr_original_motor_face_x':-67.3,'pr_motor_shift_x':-6.2,'pr_inner_backplate_thickness':2,'pr_housing_rear_overhang':4,'pr_stator_plate_thickness':3,'pr_housing_radius':36,'pr_stator_plate_radius':41,'pr_outer_race_opening':63,'pr_inner_race_land_diameter':52.5,'pr_retainer_thickness':2,'pr_spacer_diametral_clearance':.1,'pr_axial_passage_radius':7,'pr_retainer_lug_radius':37,'pr_retainer_lug_size':4.5,'pr_retainer_bolt_radius':1.7,'pr_stator_head_clearance_radius':3.15,'pr_motor_output_bolt_radius':2.2,'pr_motor_output_pcd_radius':'lc_rs02_output_pcd_radius','pr_stator_pcd_radius':'lc_carrier_stator_pcd','pr_pitch_x_offset':5}
  for key,value in values.items():self.g.parameter(key,value,comment='Frozen paired-6810 prototype. Nominal bearing sizes, structural dimensions and unqualified process allowances are independent.')
  derived={'pr_motor_face_x':'pr_original_motor_face_x+pr_motor_shift_x','pr_bearing_rear_x':'pr_motor_face_x+pr_inner_backplate_thickness','pr_bearing_front_x':'pr_bearing_rear_x+pr_bearing_center_span','pr_bearing_end_x':'pr_bearing_front_x+pr_bearing_width','pr_housing_back_x':'pr_motor_face_x-pr_housing_rear_overhang','pr_housing_split_x':'pr_housing_back_x+pr_stator_plate_thickness','pr_seat_radius':'(pr_bearing_od+pr_seat_diametral_allowance)/2','pr_journal_radius':'(pr_bearing_id-pr_journal_diametral_clearance)/2','pr_race_spacing':'pr_bearing_center_span-pr_bearing_width','pr_inner_land_radius':'pr_inner_race_land_diameter/2','pr_outer_open_radius':'pr_outer_race_opening/2'}
  for key,value in derived.items():self.g.parameter(key,value)
 def circles(self,x,definitions,name):
  g=self.g;plane=g.plane(self.c.yZConstructionPlane,x,name+' plane');sk=self.c.sketches.add(plane);sk.name=name;sk.isComputeDeferred=True
  for y,z,r in definitions:
   p=g.skeleton_point(sk,'-('+z+')',y);g.point_dimensions(sk,p,'-('+z+')',y);circle=sk.sketchCurves.sketchCircles.addByCenterRadius(p.geometry,g.mm(r)/10);sk.geometricConstraints.addCoincident(circle.centerSketchPoint,p);sk.sketchDimensions.addRadialDimension(circle,core.Point3D.create(p.geometry.x+.6,p.geometry.y+.6,0)).parameter.expression=r
  sk.isComputeDeferred=False;return sk
 def annulus(self,x,depth,ro,ri,name):
  self.parameters();g=self.g;plane=g.plane(self.c.yZConstructionPlane,x,name+' axial datum');sk=self.c.sketches.add(plane);sk.name=name+' annular section'
  for r in[ro,ri]:
   circle=sk.sketchCurves.sketchCircles.addByCenterRadius(sk.originPoint.geometry,g.mm(r)/10);sk.geometricConstraints.addCoincident(circle.centerSketchPoint,sk.originPoint);sk.sketchDimensions.addRadialDimension(circle,core.Point3D.create(g.mm(r)/10,.5,0)).parameter.expression=r
  p=next(p for p in sk.profiles if p.profileLoops.count==2);inp=self.c.features.extrudeFeatures.createInput(p,fusion.FeatureOperations.NewBodyFeatureOperation);inp.setDistanceExtent(False,g.value(depth));f=self.c.features.extrudeFeatures.add(inp);f.name=name;sk.isVisible=False;return f.bodies.item(0)
 def patterned_circle(self,body,x,depth,radius,pcd,phase,count,name,join=False):
  g=self.g;sk=self.circles(x,[(f'({pcd})*cos({phase} deg)',f'({pcd})*sin({phase} deg)',radius)],name+' seed');f=g.extrude(sk,depth,name+' seed',fusion.FeatureOperations.JoinFeatureOperation if join else fusion.FeatureOperations.CutFeatureOperation,[body]);objects=core.ObjectCollection.create();objects.add(f);inp=self.c.features.circularPatternFeatures.createInput(objects,self.c.xConstructionAxis);inp.quantity=g.value(str(count));inp.totalAngle=g.value('360 deg');inp.patternComputeOption=fusion.PatternComputeOptions.AdjustPatternCompute;f=self.c.features.circularPatternFeatures.add(inp);f.name=name+' circular pattern';assert self.c.bRepBodies.count==1;return self.c.bRepBodies.item(0)
 def spacer(self,outer):
  return self.annulus('pr_bearing_rear_x+pr_bearing_width','pr_race_spacing','(pr_bearing_od-pr_spacer_diametral_clearance)/2'if outer else'pr_inner_land_radius','pr_outer_open_radius'if outer else'(pr_bearing_id+pr_spacer_diametral_clearance)/2',('Outer'if outer else'Inner')+' bearing race spacer')
 def inner_backplate(self):
  body=self.annulus('pr_motor_face_x','pr_inner_backplate_thickness','pr_inner_land_radius','pr_axial_passage_radius','Motor-side inner race support');return self.patterned_circle(body,'pr_motor_face_x-1 mm','pr_inner_backplate_thickness+2 mm','pr_motor_output_bolt_radius','pr_motor_output_pcd_radius',0,6,'Six fixed motor-output through holes')
 def outer_retainer(self):
  body=self.annulus('pr_bearing_end_x','pr_retainer_thickness','pr_housing_radius','pr_outer_open_radius','Removable outer-race retaining plate');body=self.patterned_circle(body,'pr_bearing_end_x','pr_retainer_thickness','pr_retainer_lug_size','pr_retainer_lug_radius',20,3,'Three broad retainer lugs',True);body=self.patterned_circle(body,'pr_bearing_end_x-1 mm','pr_retainer_thickness+2 mm','pr_retainer_bolt_radius','pr_retainer_lug_radius',20,3,'Three retainer screw clearances');return self.patterned_circle(body,'pr_bearing_end_x-1 mm','pr_retainer_thickness+2 mm','pr_stator_head_clearance_radius','pr_stator_pcd_radius',0,9,'Nine open stator screw-head clearances')
